Here is a Javascript function that uses the Math.random() method to generate a cryptographically secure random integer within a given range, with the ability to generate a non-repeating set of random numbers. The function also has options for generating random decimals and for seeding the random number generator:
```
function generateRandomNumber(min, max, decimalPlaces, seed) {
  if (seed) {
    Math.seedrandom(seed);
  }
  let randomNumbers = new Set();
  let randomNumber;
  if (decimalPlaces) {
    randomNumber = Math.random() * (max - min) + min;
    randomNumber = randomNumber.toFixed(decimalPlaces);
  } else {
    randomNumber = Math.floor(Math.random() * (max - min + 1) + min);
  }
  randomNumbers.add(randomNumber);
  while (randomNumbers.size < (max - min + 1)) {
    if (decimalPlaces) {
      randomNumber = Math.random() * (max - min) + min;
      randomNumber = randomNumber.toFixed(decimalPlaces);
    } else {
      randomNumber = Math.floor(Math.random() * (max - min + 1) + min);
    }
    if (!randomNumbers.has(randomNumber)) {
      randomNumbers.add(randomNumber);
    }
  }
  return Array.from(randomNumbers);
}
```
