```
const weights = [70, 85, 63, 90, 78, 82, 68, 75];
const limit = 1000;
function getCombinations(arr, n) {
  let results = [];
  function combinate(start, prev) {
    if (prev.length === n) {
      results.push(prev);
    } else {
      for (let i = start; i < arr.length; i++) {
        if (prev.includes(1) && i === 1) continue; // exclude person 1
        if (prev.includes(2) && i === 2) continue; // exclude person 2
        combinate(i + 1, prev.concat(arr[i]));
      }
    }
  }
  combinate(0, []);
  return results;
}
let possibleCombinations = getCombinations(weights, 8);
let validCombinations = possibleCombinations.filter(combination => 
  (combination.reduce((acc, curr) => acc + curr, 0) <= limit) && 
  (combination.filter(weight => weight > 85).length <= 1) && 
  (!combination.includes(70) || !combination.includes(85))
);
console.log(validCombinations.length);
```
In the modified code, we added two conditions to exclude person 1 and person 2 from the combinations. We did this by checking if the current index `i` is 1 or 2 and if the previous combination already includes that person. 
