Here's a Java code that simulates the process of launching rockets into space:
```java
public class RocketLaunchSimulation {
    public static void main(String[] args) {
        double rocketWeight = 100000; // kg
        double gravity = 9.81; // m/s^2
        // First stage
        int firstStageDuration = 180; // seconds
        double firstStageThrust = 3 * 100000; // N
        double firstStageFuelConsumptionRate = 2000; // kg/s
        double firstStageFuel = 150000; // kg
        double firstStageMass = rocketWeight + firstStageFuel;
        double firstStageVelocity = 0; // m/s
        double firstStageAltitude = 0; // m
        for (int i = 0; i <= firstStageDuration; i++) {
            double firstStageAcceleration = (firstStageThrust - firstStageFuelConsumptionRate * gravity) / firstStageMass;
            firstStageVelocity += firstStageAcceleration;
            firstStageAltitude += firstStageVelocity;
            firstStageFuel -= firstStageFuelConsumptionRate;
            firstStageMass = rocketWeight + firstStageFuel;
            System.out.println("First stage: " + i + "s - Altitude: " + firstStageAltitude + "m - Velocity: " + firstStageVelocity + "m/s");
        }
        // Second stage
        int secondStageDuration = 300; // seconds
        double secondStageThrust = 50000; // N
        double secondStageFuelConsumptionRate = 1000; // kg/s
        double secondStageFuel = 50000; // kg
        double secondStageMass = rocketWeight + firstStageFuel + secondStageFuel;
        double secondStageVelocity = firstStageVelocity; // m/s
        double secondStageAltitude = firstStageAltitude; // m
        for (int i = 0; i <= secondStageDuration; i++) {
            double secondStageAcceleration = (secondStageThrust - secondStageFuelConsumptionRate * gravity) / secondStageMass;
            secondStageVelocity += secondStageAcceleration;
            secondStageAltitude += secondStageVelocity;
            secondStageFuel -= secondStageFuelConsumptionRate;
            secondStageMass = rocketWeight + firstStageFuel + secondStageFuel;
            System.out.println("Second stage: " + i + "s - Altitude: " + secondStageAltitude + "m - Velocity: " + secondStageVelocity + "m/s");
        }
    }
}
