To find the 2nd smallest number using the Quick Select algorithm, we can modify the algorithm to return the kth smallest element, where k is the index of the element we want to find. In this case, we want to find the 2nd smallest element, so we set k = 2.
Here is the Java code implementation to find the 2nd smallest number in the set {0, 2, 5, 22, 15, 11, 37} using the Quick Select algorithm:
```java
public class QuickSelect {
    public static int quickSelect(int[] arr, int k) {
        int left = 0;
        int right = arr.length - 1;
        while (left <= right) {
            int pivotIndex = partition(arr, left, right);
            if (pivotIndex == k - 1) {
                return arr[pivotIndex];
            } else if (pivotIndex < k - 1) {
                left = pivotIndex + 1;
            } else {
                right = pivotIndex - 1;
            }
        }
        return -1; // kth smallest element not found
    }
    private static int partition(int[] arr, int left, int right) {
        int pivot = arr[right];
        int i = left;
        for (int j = left; j < right; j++) {
            if (arr[j] <= pivot) {
                swap(arr, i, j);
                i++;
            }
        }
        swap(arr, i, right);
        return i;
    }
    private static void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
    public static void main(String[] args) {
        int[] arr = {0, 2, 5, 22, 15, 11, 37};
        int k = 2;
        int result = quickSelect(arr, k);
        System.out.println("The " + k + "nd smallest element is: " + result);
    }
}
```
