Go is a versatile programming language that can be used to conduct a comprehensive analysis and comparison of the nutritional and ingredient composition of freshly-cooked food and packaged food. To accomplish this task, we can use Go to scrape and parse data from online sources such as nutrition databases and food label databases. We can also use Go to perform statistical analysis and generate visualizations of the data.
Here is a sample code that utilizes Go to conduct a nutritional analysis and comparison of freshly-cooked food and packaged food:
```
package main
import (
    "fmt"
    "io/ioutil"
    "net/http"
    "encoding/json"
)
type NutritionData struct {
    Calories int `json:"calories"`
    Fat float64 `json:"fat"`
    Carbs float64 `json:"carbs"`
    Protein float64 `json:"protein"`
}
func main() {
    // Get nutrition data for freshly-cooked food
    freshFoodData := getNutritionData("https://api.nutritionix.com/v1_1/search/chicken%20breast?results=0:1&fields=item_name,brand_name,item_id,nf_calories,nf_total_fat,nf_total_carbohydrate,nf_protein&appId=YOUR_APP_ID&appKey=YOUR_APP_KEY")

    // Get nutrition data for packaged food
    packagedFoodData := getNutritionData("https://api.nutritionix.com/v1_1/search/mcdonalds%20big%20mac?results=0:1&fields=item_name,brand_name,item_id,nf_calories,nf_total_fat,nf_total_carbohydrate,nf_protein&appId=YOUR_APP_ID&appKey=YOUR_APP_KEY")

    // Compare the nutritional data
    fmt.Println("Freshly-Cooked Food:")
    printNutritionData(freshFoodData)
    fmt.Println("Packaged Food:")
    printNutritionData(packagedFoodData)
}
func getNutritionData(url string) NutritionData {
    resp, err := http.Get(url)
    if err != nil {
        panic(err)
    }
    defer resp.Body.Close()
    body, err := ioutil.ReadAll(resp.Body)
    if err != nil {
        panic(err)
    }
    var data struct {
        Hits []struct {
            Fields NutritionData `json:"fields"`
        } `json:"hits"`
    }
    err = json.Unmarshal(body, &data)
    if err != nil {
        panic(err)
    }
    return data.Hits[0].Fields
}
func printNutritionData(data NutritionData) {
    fmt.Printf("Calories: %d\n", data.Calories)
    fmt.Printf("Fat: %.2f g\n", data.Fat)
    fmt.Printf("Carbs: %.2f g\n", data.Carbs)
    fmt.Printf("Protein: %.2f g\n", data.Protein)
}
```
This code uses the Nutritionix API to retrieve nutrition data for freshly-cooked food and packaged food. It then compares the nutritional data and prints the results. You can modify the code to add more features such as statistical analysis and visualizations.

